    INSERT INTO ielts_parts (section_id,part_number,title,context) VALUES (v_sec,1,'Part 1','A woman phones Tom''s Computer Maintenance because her computer screen has crashed, and the technician fills in a customer information form.') RETURNING id INTO v_part;
