    INSERT INTO ielts_parts (section_id,part_number,title,context) VALUES (v_sec,2,'Part 2','The Water Project Manager of the charity Charity-Water gives a talk, telling the story of a woman named Helen in Uganda whose life changed after a new well was built.') RETURNING id INTO v_part;
    INSERT INTO ielts_question_groups (part_id,group_order,start_question_number,end_question_number,question_type,instructions,shared_content) VALUES (v_part,1,11,17,'mcq_single','Choose the correct letter, A, B or C.','{}'::jsonb) RETURNING id INTO v_grp;
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,11,'The speaker''s job requires','[{"text":"a great deal of walking.","letter":"A"},{"letter":"B","text":"extensive travel."},{"letter":"C","text":"clean water."}]'::jsonb,'"B"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,12,'Why is this story being told?','[{"letter":"A","text":"to promote Charity-Water"},{"letter":"B","text":"for entertainment purposes"},{"text":"to encourage Helen","letter":"C"}]'::jsonb,'"A"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,13,'Why do the charity workers usually surprise communities?','[{"letter":"A","text":"It makes people happy."},{"text":"It is difficult to spread news.","letter":"B"},{"letter":"C","text":"It makes their work easier."}]'::jsonb,'"C"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,14,'When villagers heard of the charity workers'' arrival, they','[{"letter":"A","text":"had a party."},{"letter":"B","text":"were suspicious."},{"text":"took no notice.","letter":"C"}]'::jsonb,'"A"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,15,'Helen is feeling','[{"text":"ecstatic about her new life.","letter":"A"},{"letter":"B","text":"curious about the charity workers."},{"text":"nostalgic about her old life.","letter":"C"}]'::jsonb,'"A"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,16,'What did the speaker notice about Helen?','[{"letter":"A","text":"that she had bathed recently"},{"text":"the care she took with her appearance","letter":"B"},{"letter":"C","text":"that she was wearing a green uniform"}]'::jsonb,'"B"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,17,'Making someone feel beautiful was','[{"text":"part of the speaker''s job description.","letter":"A"},{"text":"an unexpected bonus for the speaker.","letter":"B"},{"letter":"C","text":"of little importance to the speaker."}]'::jsonb,'"B"'::jsonb);
    INSERT INTO ielts_question_groups (part_id,group_order,start_question_number,end_question_number,question_type,instructions,shared_content) VALUES (v_part,2,18,20,'mcq_single','In what THREE ways did the new well improve Helen''s life? Choose THREE letters A - G.','{}'::jsonb) RETURNING id INTO v_grp;
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,18,'In what way did the new well improve Helen''s life? (one of three)','[{"letter":"A","text":"Her children enjoyed better health"},{"text":"It increased her household income","letter":"B"},{"text":"It gave her more free time","letter":"C"},{"letter":"D","text":"She got a leadership position"},{"text":"She had more choices and options","letter":"E"},{"letter":"F","text":"She made new friends in her village"},{"text":"It allowed her to go to school.","letter":"G"}]'::jsonb,'"C"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,19,'In what way did the new well improve Helen''s life? (one of three)','[{"text":"Her children enjoyed better health","letter":"A"},{"letter":"B","text":"It increased her household income"},{"text":"It gave her more free time","letter":"C"},{"letter":"D","text":"She got a leadership position"},{"text":"She had more choices and options","letter":"E"},{"text":"She made new friends in her village","letter":"F"},{"letter":"G","text":"It allowed her to go to school."}]'::jsonb,'"D"'::jsonb);
    INSERT INTO ielts_questions (group_id,question_number,stem,options,correct_answer) VALUES (v_grp,20,'In what way did the new well improve Helen''s life? (one of three)','[{"letter":"A","text":"Her children enjoyed better health"},{"letter":"B","text":"It increased her household income"},{"letter":"C","text":"It gave her more free time"},{"letter":"D","text":"She got a leadership position"},{"letter":"E","text":"She had more choices and options"},{"text":"She made new friends in her village","letter":"F"},{"letter":"G","text":"It allowed her to go to school."}]'::jsonb,'"E"'::jsonb);
